namespace Coplt.Mathematics.Algebras.Generics;

/// <summary>
/// The dispatch of the value of an algebra to the visitor that reaches it
/// <para>The interfaces of the visitors are generated by
/// <c>Coplt.Analyzers.Generators.AlgebraVisitorGenerator</c>, every one of them is the interface of a count of
/// the values that the members of it take</para>
/// </summary>
public interface INumberAlgebraDispatch<TSelf> : INumberAlgebra<TSelf>
    where TSelf : unmanaged, INumberAlgebraDispatch<TSelf>
{
    /// <summary>Hands the value of <paramref name="self"/> to <typeparamref name="V"/></summary>
    /// <typeparam name="V">The type of the visitor that reaches the value</typeparam>
    /// <param name="self">The value to hand over</param>
    /// <returns>The value the visitor built</returns>
    public static abstract TSelf Visit_Self<V>(in TSelf self)
        where V : INumberAlgebraVisitor_Self_Self<V>;

    /// <summary>Hands the value of <paramref name="a"/> and <paramref name="b"/> to <typeparamref name="V"/></summary>
    /// <typeparam name="V">The type of the visitor that reaches the values</typeparam>
    /// <param name="a">The first value to hand over</param>
    /// <param name="b">The second value to hand over</param>
    /// <returns>The value the visitor built</returns>
    public static abstract TSelf Visit_Self<V>(in TSelf a, in TSelf b)
        where V : INumberAlgebraVisitor_Self_Self_Self<V>;

    /// <summary>
    /// Hands the value of <paramref name="a"/>, <paramref name="b"/> and <paramref name="c"/> to
    /// <typeparamref name="V"/>
    /// </summary>
    /// <typeparam name="V">The type of the visitor that reaches the values</typeparam>
    /// <param name="a">The first value to hand over</param>
    /// <param name="b">The second value to hand over</param>
    /// <param name="c">The third value to hand over</param>
    /// <returns>The value the visitor built</returns>
    public static abstract TSelf Visit_Self<V>(in TSelf a, in TSelf b, in TSelf c)
        where V : INumberAlgebraVisitor_Self_Self_Self_Self<V>;
}

public interface INumberAlgebraDispatch<TSelf, TScalar> : INumberAlgebraDispatch<TSelf>, INumberAlgebra<TSelf, TScalar>
    where TSelf : unmanaged, INumberAlgebraDispatch<TSelf, TScalar>
    where TScalar : unmanaged, IBinaryNumber<TScalar>
{
    public static abstract TSelf Visit_Self<V>(in TSelf a, TScalar b)
        where V : INumberAlgebraVisitor_Self_Scalar_Self<V, TScalar>;

    public static abstract TSelf Visit_Self<V>(in TSelf a, TScalar b, TScalar c)
        where V : INumberAlgebraVisitor_Self_Scalar_Scalar_Self<V, TScalar>;
}
